244	export async function saveContent(
245	    db: AppDatabase,
246	    playlistId: string,
247	    streams: Array<Record<string, unknown>>,
248	    type: 'live' | 'movie' | 'series',
249	    control?: OperationControl
250	): Promise<{ success: boolean; count: number }> {
251	    const dbType =
252	        type === 'series' ? 'series' : type === 'movie' ? 'movies' : 'live';
253	
254	    const existingContent = await db
255	        .select({ count: sql<number>`count(*)` })
256	        .from(schema.content)
257	        .innerJoin(
258	            schema.categories,
259	            eq(schema.content.categoryId, schema.categories.id)
260	        )
261	        .where(
262	            and(
263	                eq(schema.categories.playlistId, playlistId),
264	                eq(schema.categories.type, dbType),
265	                eq(schema.content.type, type)
266	            )
267	        );
268	
269	    if ((existingContent[0]?.count ?? 0) > 0) {
270	        return { success: true, count: existingContent[0].count };
271	    }
272	
273	    const categories = await db
274	        .select({
275	            id: schema.categories.id,
276	            xtreamId: schema.categories.xtreamId,
277	        })
278	        .from(schema.categories)
279	        .where(
280	            and(
281	                eq(schema.categories.playlistId, playlistId),
282	                eq(schema.categories.type, dbType)
283	            )
284	        );
285	
286	    const categoryMap = new Map(categories.map((category) => [
287	        category.xtreamId,
288	        category.id,
289	    ]));
290	
291	    const values = streams
292	        .map((stream) => toXtreamContentValue(stream, type, categoryMap))
293	        .filter((value): value is XtreamContentValue => value !== null);
294	
295	    const total = values.length;
296	    const chunkSize = 100;
297	    let totalInserted = 0;
298	
299	    for (let index = 0; index < values.length; index += chunkSize) {
300	        await checkpointOperation(control);
301	        const chunk = values.slice(index, index + chunkSize);
302	        await db
303	            .insert(schema.content)
304	            .values(chunk)
305	            .onConflictDoNothing({
306	                target: [
307	                    schema.content.categoryId,
308	                    schema.content.type,
309	                    schema.content.xtreamId,
310	                ],
311	            });
312	        totalInserted += chunk.length;
313	        await reportOperationProgress(control, {
314	            phase: 'saving-content',
315	            current: totalInserted,
316	            total,
317	            increment: chunk.length,
318	        });
319	    }
320	
321	    return { success: true, count: totalInserted };
322	}
