324	export async function clearXtreamImportCache(
325	    db: AppDatabase,
326	    playlistId: string,
327	    type: 'live' | 'movie' | 'series'
328	): Promise<{ success: boolean }> {
329	    const dbType =
330	        type === 'series' ? 'series' : type === 'movie' ? 'movies' : 'live';
331	
332	    const categoryRows = await db
333	        .select({ id: schema.categories.id })
334	        .from(schema.categories)
335	        .where(
336	            and(
337	                eq(schema.categories.playlistId, playlistId),
338	                eq(schema.categories.type, dbType)
339	            )
340	        );
341	
342	    const categoryIds = categoryRows.map((category) => category.id);
343	    if (categoryIds.length === 0) {
344	        return { success: true };
345	    }
346	
347	    const contentRows = await db
348	        .select({ id: schema.content.id })
349	        .from(schema.content)
350	        .where(inArray(schema.content.categoryId, categoryIds));
351	
352	    for (const chunk of chunkValues(
353	        contentRows.map((row) => row.id),
354	        100
355	    )) {
356	        await db.delete(schema.content).where(inArray(schema.content.id, chunk));
357	    }
358	
359	    for (const chunk of chunkValues(categoryIds, 100)) {
360	        await db
361	            .delete(schema.categories)
362	            .where(inArray(schema.categories.id, chunk));
363	    }
364	
365	    return { success: true };
366	}
