368	export async function getContentByXtreamId(
369	    db: AppDatabase,
370	    xtreamId: number,
371	    playlistId: string,
372	    contentType?: 'live' | 'movie' | 'series'
373	) {
374	    const conditions = [
375	        eq(schema.content.xtreamId, xtreamId),
376	        eq(schema.categories.playlistId, playlistId),
377	    ];
378	
379	    if (contentType) {
380	        conditions.push(eq(schema.content.type, contentType));
381	    }
382	
383	    const result = await db
384	        .select(selectContentFields())
385	        .from(schema.content)
386	        .innerJoin(
387	            schema.categories,
388	            eq(schema.content.categoryId, schema.categories.id)
389	        )
390	        .where(and(...conditions))
391	        .limit(1);
392	
393	    return result[0] || null;
