396	export async function searchContent(
397	    db: AppDatabase,
398	    playlistId: string,
399	    searchTerm: string,
400	    types: string[],
401	    excludeHidden = false
402	) {
403	    if (!types || types.length === 0) {
404	        return [];
405	    }
406	
407	    const searchTermLower = searchTerm.toLocaleLowerCase();
408	    const likePatterns = buildLikePatterns(searchTerm);
409	    const likeConditions = likePatterns.map(
410	        (pattern) => sql`${schema.content.title} LIKE ${pattern} ESCAPE '\\'`
411	    );
412	
413	    const conditions = [
414	        eq(schema.categories.playlistId, playlistId),
415	        inArray(schema.content.type, types as Array<'live' | 'movie' | 'series'>),
416	        or(...likeConditions),
417	    ];
418	
419	    if (excludeHidden) {
420	        conditions.push(eq(schema.categories.hidden, false));
421	    }
422	
423	    const candidates = await db
424	        .select(selectContentFields())
425	        .from(schema.content)
426	        .innerJoin(
427	            schema.categories,
428	            eq(schema.content.categoryId, schema.categories.id)
429	        )
430	        .where(and(...conditions))
431	        .limit(200);
432	
433	    return candidates
434	        .filter((item) =>
435	            item.title?.toLocaleLowerCase().includes(searchTermLower)
436	        )
437	        .slice(0, 50);
438	}
