import { and, asc, desc, eq, inArray, or, sql } from 'drizzle-orm';
import * as schema from 'database-schema';
import type { AppDatabase } from '../database.types';
import {
    checkpointOperation,
    chunkValues,
    type OperationControl,
    reportOperationProgress,
} from './operation-control';

function escapeLikePattern(term: string): string {
    return term.replace(/[%_\\]/g, '\\$&');
}

function buildLikePatterns(term: string): string[] {
    const variants = new Set<string>();
    const titleCase =
        term.length > 0
            ? term.charAt(0).toLocaleUpperCase() +
              term.slice(1).toLocaleLowerCase()
            : term;

    variants.add(term);
    variants.add(term.toLocaleLowerCase());
    variants.add(term.toLocaleUpperCase());
    variants.add(titleCase);

    return [...variants].map((value) => `%${escapeLikePattern(value)}%`);
}

export type GlobalRecentlyAddedKind = 'all' | 'vod' | 'series';

function getRecentlyAddedContentTypes(
    kind: GlobalRecentlyAddedKind
): Array<'movie' | 'series'> {
    if (kind === 'vod') {
        return ['movie'];
    }

    if (kind === 'series') {
        return ['series'];
    }

    return ['movie', 'series'];
}

function selectContentFields() {
    return {
        id: schema.content.id,
        category_id: schema.content.categoryId,
        title: schema.content.title,
        rating: schema.content.rating,
        added: schema.content.added,
        poster_url: schema.content.posterUrl,
        epg_channel_id: schema.content.epgChannelId,
        tv_archive: schema.content.tvArchive,
        tv_archive_duration: schema.content.tvArchiveDuration,
        direct_source: schema.content.directSource,
        xtream_id: schema.content.xtreamId,
        type: schema.content.type,
    };
}

export async function hasContent(
    db: AppDatabase,
    playlistId: string,
    type: 'live' | 'movie' | 'series'
): Promise<boolean> {
    const result = await db
        .select({ count: sql<number>`count(*)` })
        .from(schema.content)
        .innerJoin(
            schema.categories,
            eq(schema.content.categoryId, schema.categories.id)
        )
        .where(
            and(
                eq(schema.categories.playlistId, playlistId),
                eq(schema.content.type, type)
            )
        );

    return result[0].count > 0;
}

export async function getContent(
    db: AppDatabase,
    playlistId: string,
    type: 'live' | 'movie' | 'series'
) {
    const baseQuery = db
        .select(selectContentFields())
        .from(schema.content)
        .innerJoin(
            schema.categories,
            eq(schema.content.categoryId, schema.categories.id)
        )
        .where(
            and(
                eq(schema.categories.playlistId, playlistId),
                eq(schema.content.type, type)
            )
        );

    return type === 'live'
        ? baseQuery.orderBy(asc(schema.content.id))
        : baseQuery.orderBy(desc(schema.content.added));
}

export async function getGlobalRecentlyAdded(
    db: AppDatabase,
    kind: GlobalRecentlyAddedKind = 'all',
    limit = 200
) {
    const contentTypes = getRecentlyAddedContentTypes(kind);
    const normalizedLimit = Number.isFinite(limit)
        ? Math.min(Math.max(Math.trunc(limit), 1), 200)
        : 200;
    const addedOrder = sql<number>`CAST(${schema.content.added} AS INTEGER)`;

    return db
        .select({
            ...selectContentFields(),
            added_at: schema.content.added,
            playlist_id: schema.playlists.id,
            playlist_name: schema.playlists.name,
        })
        .from(schema.content)
        .innerJoin(
            schema.categories,
            eq(schema.content.categoryId, schema.categories.id)
        )
        .innerJoin(
            schema.playlists,
            eq(schema.categories.playlistId, schema.playlists.id)
        )
        .where(
            and(
                inArray(schema.content.type, contentTypes),
                eq(schema.categories.hidden, false),
                sql`${schema.content.added} <> ''`
            )
        )
        .orderBy(desc(addedOrder))
        .limit(normalizedLimit);
}

type XtreamContentValue = {
    categoryId: number;
    title: string;
    rating: string;
    added: string;
    posterUrl: string;
    epgChannelId?: string | null;
    tvArchive?: number | null;
    tvArchiveDuration?: number | null;
    directSource?: string | null;
    xtreamId: number;
    type: 'live' | 'movie' | 'series';
};

type XtreamContentSource = Record<string, unknown> & {
    category_id?: string | number;
    rating?: string | number;
    rating_imdb?: string;
    last_modified?: string;
    added?: string;
    stream_icon?: string;
        poster?: string;
        cover?: string;
        name?: string;
        title?: string;
        epg_channel_id?: string;
        tv_archive?: string | number;
        tv_archive_duration?: string | number;
        direct_source?: string;
        series_id?: string | number;
        stream_id?: string | number;
};

function toXtreamContentValue(
    stream: Record<string, unknown>,
    type: 'live' | 'movie' | 'series',
    categoryMap: Map<number, number>
): XtreamContentValue | null {
    const source = stream as XtreamContentSource;
    const streamCategoryId =
        type === 'series'
            ? parseInt(String(source.category_id || '0'))
            : parseInt(String(source.category_id));

    const categoryId = categoryMap.get(streamCategoryId);
    if (!categoryId) {
        return null;
    }

    const title =
        type === 'series'
            ? source.title ||
              source.name ||
              `Unknown Series ${source.series_id ?? ''}`.trim()
            : source.name ||
              source.title ||
              `Unknown Stream ${source.stream_id ?? ''}`.trim();

    return {
        categoryId,
        title,
        rating: String(source.rating || source.rating_imdb || ''),
        added:
            type === 'series'
                ? String(source.last_modified || '')
                : String(source.added || ''),
        posterUrl: String(
            source.stream_icon || source.poster || source.cover || ''
        ),
        epgChannelId:
            type === 'live'
                ? String(source.epg_channel_id ?? '').trim() || null
                : null,
        tvArchive:
            type === 'live'
                ? Number.parseInt(String(source.tv_archive ?? '0'), 10) || 0
                : null,
        tvArchiveDuration:
            type === 'live'
                ? Number.parseInt(
                      String(source.tv_archive_duration ?? '0'),
                      10
                  ) || 0
                : null,
        directSource:
            type === 'live'
                ? String(source.direct_source ?? '').trim() || null
                : null,
        xtreamId:
            type === 'series'
                ? parseInt(String(source.series_id || '0'))
                : parseInt(String(source.stream_id || '0')),
        type,
    };
}

export async function saveContent(
    db: AppDatabase,
    playlistId: string,
    streams: Array<Record<string, unknown>>,
    type: 'live' | 'movie' | 'series',
    control?: OperationControl
): Promise<{ success: boolean; count: number }> {
    const dbType =
        type === 'series' ? 'series' : type === 'movie' ? 'movies' : 'live';

    const existingContent = await db
        .select({ count: sql<number>`count(*)` })
        .from(schema.content)
        .innerJoin(
            schema.categories,
            eq(schema.content.categoryId, schema.categories.id)
        )
        .where(
            and(
                eq(schema.categories.playlistId, playlistId),
                eq(schema.categories.type, dbType),
                eq(schema.content.type, type)
            )
        );

    if ((existingContent[0]?.count ?? 0) > 0) {
        return { success: true, count: existingContent[0].count };
    }

    const categories = await db
        .select({
            id: schema.categories.id,
            xtreamId: schema.categories.xtreamId,
        })
        .from(schema.categories)
        .where(
            and(
                eq(schema.categories.playlistId, playlistId),
                eq(schema.categories.type, dbType)
            )
        );

    const categoryMap = new Map(categories.map((category) => [
        category.xtreamId,
        category.id,
    ]));

    const values = streams
        .map((stream) => toXtreamContentValue(stream, type, categoryMap))
        .filter((value): value is XtreamContentValue => value !== null);

    const total = values.length;
    const chunkSize = 100;
    let totalInserted = 0;

    for (let index = 0; index < values.length; index += chunkSize) {
        await checkpointOperation(control);
        const chunk = values.slice(index, index + chunkSize);
        await db
            .insert(schema.content)
            .values(chunk)
            .onConflictDoNothing({
                target: [
                    schema.content.categoryId,
                    schema.content.type,
                    schema.content.xtreamId,
                ],
            });
        totalInserted += chunk.length;
        await reportOperationProgress(control, {
            phase: 'saving-content',
            current: totalInserted,
            total,
            increment: chunk.length,
        });
    }

    return { success: true, count: totalInserted };
}

export async function clearXtreamImportCache(
    db: AppDatabase,
    playlistId: string,
    type: 'live' | 'movie' | 'series'
): Promise<{ success: boolean }> {
    const dbType =
        type === 'series' ? 'series' : type === 'movie' ? 'movies' : 'live';

    const categoryRows = await db
        .select({ id: schema.categories.id })
        .from(schema.categories)
        .where(
            and(
                eq(schema.categories.playlistId, playlistId),
                eq(schema.categories.type, dbType)
            )
        );

    const categoryIds = categoryRows.map((category) => category.id);
    if (categoryIds.length === 0) {
        return { success: true };
    }

    const contentRows = await db
        .select({ id: schema.content.id })
        .from(schema.content)
        .where(inArray(schema.content.categoryId, categoryIds));

    for (const chunk of chunkValues(
        contentRows.map((row) => row.id),
        100
    )) {
        await db.delete(schema.content).where(inArray(schema.content.id, chunk));
    }

    for (const chunk of chunkValues(categoryIds, 100)) {
        await db
            .delete(schema.categories)
            .where(inArray(schema.categories.id, chunk));
    }

    return { success: true };
}

export async function getContentByXtreamId(
    db: AppDatabase,
    xtreamId: number,
    playlistId: string,
    contentType?: 'live' | 'movie' | 'series'
) {
    const conditions = [
        eq(schema.content.xtreamId, xtreamId),
        eq(schema.categories.playlistId, playlistId),
    ];

    if (contentType) {
        conditions.push(eq(schema.content.type, contentType));
    }

    const result = await db
        .select(selectContentFields())
        .from(schema.content)
        .innerJoin(
            schema.categories,
            eq(schema.content.categoryId, schema.categories.id)
        )
        .where(and(...conditions))
        .limit(1);

    return result[0] || null;
}

export async function searchContent(
    db: AppDatabase,
    playlistId: string,
    searchTerm: string,
    types: string[],
    excludeHidden = false
) {
    if (!types || types.length === 0) {
        return [];
    }

    const searchTermLower = searchTerm.toLocaleLowerCase();
    const likePatterns = buildLikePatterns(searchTerm);
    const likeConditions = likePatterns.map(
        (pattern) => sql`${schema.content.title} LIKE ${pattern} ESCAPE '\\'`
    );

    const conditions = [
        eq(schema.categories.playlistId, playlistId),
        inArray(schema.content.type, types as Array<'live' | 'movie' | 'series'>),
        or(...likeConditions),
    ];

    if (excludeHidden) {
        conditions.push(eq(schema.categories.hidden, false));
    }

    const candidates = await db
        .select(selectContentFields())
        .from(schema.content)
        .innerJoin(
            schema.categories,
            eq(schema.content.categoryId, schema.categories.id)
        )
        .where(and(...conditions))
        .limit(200);

    return candidates
        .filter((item) =>
            item.title?.toLocaleLowerCase().includes(searchTermLower)
        )
        .slice(0, 50);
}

export async function globalSearch(
    db: AppDatabase,
    searchTerm: string,
    types: string[],
    excludeHidden = false
) {
    if (!types || types.length === 0) {
        return [];
    }

    const searchTermLower = searchTerm.toLocaleLowerCase();
    const likePatterns = buildLikePatterns(searchTerm);
    const likeConditions = likePatterns.map(
        (pattern) => sql`${schema.content.title} LIKE ${pattern} ESCAPE '\\'`
    );

    const conditions = [
        inArray(schema.content.type, types as Array<'live' | 'movie' | 'series'>),
        or(...likeConditions),
    ];

    if (excludeHidden) {
        conditions.push(eq(schema.categories.hidden, false));
    }

    const candidates = await db
        .select({
            ...selectContentFields(),
            playlist_id: schema.categories.playlistId,
            playlist_name: schema.playlists.name,
        })
        .from(schema.content)
        .innerJoin(
            schema.categories,
            eq(schema.content.categoryId, schema.categories.id)
        )
        .innerJoin(
            schema.playlists,
            eq(schema.categories.playlistId, schema.playlists.id)
        )
        .where(and(...conditions))
        .orderBy(schema.content.title)
        .limit(200);

    return candidates
        .filter((item) =>
            item.title?.toLocaleLowerCase().includes(searchTermLower)
        )
        .slice(0, 50);
}

/**
 * Drizzle ORM schema for IPTVnator database
 * This schema defines the structure for Xtream Codes API data storage
 *
 * Single source of truth for database schema - used by:
 * - electron-backend (full read-write access)
 * - agent-backend (read-only access for AI queries)
 */

import { sql } from 'drizzle-orm';
import {
    index,
    integer,
    sqliteTable,
    text,
    uniqueIndex,
} from 'drizzle-orm/sqlite-core';

// Playlists table
export const playlists = sqliteTable('playlists', {
    id: text('id').primaryKey(),
    name: text('name').notNull(),
    serverUrl: text('serverUrl'),
    username: text('username'),
    password: text('password'),
    dateCreated: text('date_created').default(sql`CURRENT_TIMESTAMP`),
    lastUpdated: text('last_updated'),
    type: text('type', {
        enum: ['xtream', 'stalker', 'm3u-file', 'm3u-text', 'm3u-url'],
    }).notNull(),
    userAgent: text('userAgent'),
    origin: text('origin'),
    referrer: text('referrer'),
    filePath: text('filePath'),
    autoRefresh: integer('autoRefresh', { mode: 'boolean' }).default(false),
    macAddress: text('macAddress'),
    url: text('url'),
    portalUrl: text('portal_url'),
    count: integer('count'),
    importDate: text('import_date'),
    updateDate: integer('update_date'),
    position: integer('position'),
    favorites: text('favorites'),
    recentlyViewed: text('recently_viewed'),
    payload: text('payload'),
    lastUsage: text('last_usage'),
});

// App key-value state table (e.g. one-time migration flags)
export const appState = sqliteTable('app_state', {
    key: text('key').primaryKey(),
    value: text('value').notNull(),
    updatedAt: text('updated_at').default(sql`CURRENT_TIMESTAMP`),
});

// Categories table
export const categories = sqliteTable(
    'categories',
    {
        id: integer('id').primaryKey({ autoIncrement: true }),
        playlistId: text('playlist_id')
            .notNull()
            .references(() => playlists.id, { onDelete: 'cascade' }),
        name: text('name').notNull(),
        type: text('type', { enum: ['live', 'movies', 'series'] }).notNull(),
        xtreamId: integer('xtream_id').notNull(),
        hidden: integer('hidden', { mode: 'boolean' }).default(false),
    },
    (table) => ({
        playlistIdx: index('idx_categories_playlist').on(table.playlistId),
        typeIdx: index('idx_categories_type').on(table.type),
        playlistTypeXtreamUnique: uniqueIndex(
            'categories_playlist_type_xtream_unique'
        ).on(table.playlistId, table.type, table.xtreamId),
    })
);

// Content table (streams/VODs/series)
export const content = sqliteTable(
    'content',
    {
        id: integer('id').primaryKey({ autoIncrement: true }),
        categoryId: integer('category_id')
            .notNull()
            .references(() => categories.id, { onDelete: 'cascade' }),
        title: text('title').notNull(),
        rating: text('rating'),
        added: text('added'),
        posterUrl: text('poster_url'),
        backdropUrl: text('backdrop_url'),
        epgChannelId: text('epg_channel_id'),
        tvArchive: integer('tv_archive'),
        tvArchiveDuration: integer('tv_archive_duration'),
        directSource: text('direct_source'),
        xtreamId: integer('xtream_id').notNull(),
        type: text('type', { enum: ['live', 'movie', 'series'] }).notNull(),
    },
    (table) => ({
        typeIdx: index('idx_content_type').on(table.type),
        categoryIdx: index('idx_content_category').on(table.categoryId),
        titleIdx: index('idx_content_title').on(table.title),
        xtreamIdx: index('idx_content_xtream').on(table.xtreamId),
        categoryTypeXtreamUnique: uniqueIndex(
            'content_category_type_xtream_unique'
        ).on(table.categoryId, table.type, table.xtreamId),
        typeAddedIdx: index('idx_content_type_added').on(
            table.type,
            table.added
        ),
    })
);

// Recently viewed table
export const recentlyViewed = sqliteTable(
    'recently_viewed',
    {
        id: integer('id').primaryKey({ autoIncrement: true }),
        contentId: integer('content_id')
            .notNull()
            .references(() => content.id, { onDelete: 'cascade' }),
        playlistId: text('playlist_id')
            .notNull()
            .references(() => playlists.id, { onDelete: 'cascade' }),
        viewedAt: text('viewed_at').default(sql`CURRENT_TIMESTAMP`),
    },
    (table) => ({
        contentPlaylistUnique: uniqueIndex(
            'recently_viewed_content_playlist_unique'
        ).on(table.contentId, table.playlistId),
        playlistIdx: index('recently_viewed_playlist_idx').on(table.playlistId),
        viewedAtIdx: index('recently_viewed_viewed_at_idx').on(table.viewedAt),
    })
);

// Favorites table
export const favorites = sqliteTable(
    'favorites',
    {
        id: integer('id').primaryKey({ autoIncrement: true }),
        contentId: integer('content_id')
            .notNull()
            .references(() => content.id, { onDelete: 'cascade' }),
        playlistId: text('playlist_id')
            .notNull()
            .references(() => playlists.id, { onDelete: 'cascade' }),
        addedAt: text('added_at').default(sql`CURRENT_TIMESTAMP`),
        /** Display order position in the global favorites list (lower = first) */
        position: integer('position').default(0),
    },
    (table) => ({
        contentPlaylistUnique: uniqueIndex(
            'favorites_content_playlist_unique'
        ).on(table.contentId, table.playlistId),
        playlistIdx: index('favorites_playlist_idx').on(table.playlistId),
        contentIdx: index('favorites_content_idx').on(table.contentId),
    })
);

// EPG Channels table
export const epgChannels = sqliteTable(
    'epg_channels',
    {
        id: text('id').primaryKey(), // Channel ID from EPG source
        displayName: text('display_name').notNull(),
        iconUrl: text('icon_url'),
        url: text('url'),
        sourceUrl: text('source_url').notNull(), // Which EPG URL this came from
        updatedAt: text('updated_at').default(sql`CURRENT_TIMESTAMP`),
    },
    (table) => ({
        sourceIdx: index('idx_epg_channels_source').on(table.sourceUrl),
        nameIdx: index('idx_epg_channels_name').on(table.displayName),
    })
);

// EPG Programs table
export const epgPrograms = sqliteTable(
    'epg_programs',
    {
        id: integer('id').primaryKey({ autoIncrement: true }),
        channelId: text('channel_id')
            .notNull()
            .references(() => epgChannels.id, { onDelete: 'cascade' }),
        start: text('start').notNull(), // ISO datetime
        stop: text('stop').notNull(), // ISO datetime
        title: text('title').notNull(),
        description: text('description'),
        category: text('category'),
        iconUrl: text('icon_url'),
        rating: text('rating'),
        episodeNum: text('episode_num'),
    },
    (table) => ({
        channelIdx: index('idx_epg_programs_channel').on(table.channelId),
        startIdx: index('idx_epg_programs_start').on(table.start),
        stopIdx: index('idx_epg_programs_stop').on(table.stop),
        timeRangeIdx: index('idx_epg_programs_time_range').on(
            table.channelId,
            table.start,
            table.stop
        ),
    })
);

// Playback Positions table
export const playbackPositions = sqliteTable(
    'playback_positions',
    {
        id: integer('id').primaryKey({ autoIncrement: true }),
        playlistId: text('playlist_id')
            .notNull()
            .references(() => playlists.id, { onDelete: 'cascade' }),
        // For VOD: store xtream_id of the movie
        // For Series: store episode ID (from XtreamSerieEpisode.id)
        contentXtreamId: integer('content_xtream_id').notNull(),
        // 'vod' | 'episode'
        contentType: text('content_type', {
            enum: ['vod', 'episode'],
        }).notNull(),
        // For episodes: store series xtream_id for grouping
        seriesXtreamId: integer('series_xtream_id'),
        // For episodes: store season and episode numbers for display
        seasonNumber: integer('season_number'),
        episodeNumber: integer('episode_number'),
        // Playback position in seconds
        positionSeconds: integer('position_seconds').notNull().default(0),
        // Total duration in seconds (for percentage calculation)
        durationSeconds: integer('duration_seconds'),
        // Last updated timestamp
        updatedAt: text('updated_at').default(sql`CURRENT_TIMESTAMP`),
    },
    (table) => ({
        // Unique constraint: one position per content per playlist
        contentPlaylistUnique: uniqueIndex(
            'playback_positions_content_playlist_unique'
        ).on(table.contentXtreamId, table.playlistId, table.contentType),
        playlistIdx: index('playback_positions_playlist_idx').on(
            table.playlistId
        ),
        seriesIdx: index('playback_positions_series_idx').on(
            table.seriesXtreamId
        ),
        updatedIdx: index('playback_positions_updated_idx').on(table.updatedAt),
    })
);

// Type exports for TypeScript
export type Playlist = typeof playlists.$inferSelect;
export type NewPlaylist = typeof playlists.$inferInsert;
export type AppState = typeof appState.$inferSelect;
export type NewAppState = typeof appState.$inferInsert;

export type Category = typeof categories.$inferSelect;
export type NewCategory = typeof categories.$inferInsert;

export type Content = typeof content.$inferSelect;
export type NewContent = typeof content.$inferInsert;

export type RecentlyViewed = typeof recentlyViewed.$inferSelect;
export type NewRecentlyViewed = typeof recentlyViewed.$inferInsert;

export type Favorite = typeof favorites.$inferSelect;
export type NewFavorite = typeof favorites.$inferInsert;

export type EpgChannel = typeof epgChannels.$inferSelect;
export type NewEpgChannel = typeof epgChannels.$inferInsert;

export type EpgProgramDb = typeof epgPrograms.$inferSelect;
export type NewEpgProgramDb = typeof epgPrograms.$inferInsert;

export type PlaybackPosition = typeof playbackPositions.$inferSelect;
export type NewPlaybackPosition = typeof playbackPositions.$inferInsert;

// Downloads table
export const downloads = sqliteTable(
    'downloads',
    {
        id: integer('id').primaryKey({ autoIncrement: true }),
        playlistId: text('playlist_id')
            .notNull()
            .references(() => playlists.id, { onDelete: 'cascade' }),
        // Content identifiers
        xtreamId: integer('xtream_id').notNull(),
        contentType: text('content_type', {
            enum: ['vod', 'episode'],
        }).notNull(),
        // For episodes: store series info
        seriesXtreamId: integer('series_xtream_id'),
        seasonNumber: integer('season_number'),
        episodeNumber: integer('episode_number'),
        // Download metadata
        title: text('title').notNull(),
        url: text('url').notNull(),
        fileName: text('file_name'),
        filePath: text('file_path'),
        posterUrl: text('poster_url'),
        // Download progress
        status: text('status', {
            enum: ['queued', 'downloading', 'completed', 'failed', 'canceled'],
        })
            .notNull()
            .default('queued'),
        bytesDownloaded: integer('bytes_downloaded').default(0),
        totalBytes: integer('total_bytes'),
        errorMessage: text('error_message'),
        // Timestamps
        createdAt: text('created_at').default(sql`CURRENT_TIMESTAMP`),
        updatedAt: text('updated_at').default(sql`CURRENT_TIMESTAMP`),
    },
    (table) => ({
        playlistIdx: index('downloads_playlist_idx').on(table.playlistId),
        statusIdx: index('downloads_status_idx').on(table.status),
        xtreamPlaylistUnique: uniqueIndex(
            'downloads_xtream_playlist_unique'
        ).on(table.xtreamId, table.playlistId, table.contentType),
    })
);

export type Download = typeof downloads.$inferSelect;
export type NewDownload = typeof downloads.$inferInsert;

