670	    private async loadM3uPlaylistFavorites(
671	        playlistMeta: PlaylistMeta
672	    ): Promise<DashboardFavoriteItem[]> {
673	        const playlist = (await firstValueFrom(
674	            this.playlistsService.getPlaylistById(playlistMeta._id)
675	        )) as Playlist & {
676	            playlist?: {
677	                items?: Channel[];
678	            };
679	        };
680	        const favorites = Array.isArray(playlist?.favorites)
681	            ? playlist.favorites.filter(
682	                  (favorite): favorite is string =>
683	                      typeof favorite === 'string' && favorite.trim().length > 0
684	              )
685	            : [];
686	
687	        if (favorites.length === 0) {
688	            return [];
689	        }
690	
691	        const items: Channel[] = Array.isArray(playlist?.playlist?.items)
692	            ? (playlist.playlist.items as Channel[])
693	            : [];
694	        const fallbackTimestamp =
695	            this.getM3uFavoriteTimestamp(playlistMeta) ??
696	            new Date(0).toISOString();
697	
698	        return items.reduce<DashboardFavoriteItem[]>((acc, channel) => {
699	            const channelId = String(channel.id ?? '').trim();
700	            const channelUrl = String(channel.url ?? '').trim();
701	            const matchedFavoriteId = favorites.find(
702	                (favorite) => favorite === channelId || favorite === channelUrl
703	            );
704	
705	            if (!matchedFavoriteId) {
706	                return acc;
707	            }
708	
709	            acc.push({
710	                id: matchedFavoriteId,
711	                title: channel.name?.trim() || channel.tvg?.name || channelId,
712	                type: 'live',
713	                playlist_id: playlistMeta._id,
714	                playlist_name:
715	                    playlistMeta.title || playlistMeta.filename || 'M3U',
716	                added_at: fallbackTimestamp,
717	                category_id: 'live',
718	                xtream_id: matchedFavoriteId,
719	                poster_url: channel.tvg?.logo || undefined,
720	                source: 'm3u',
721	            });
722	            return acc;
723	        }, []);
724	    }
