        this.data
            .globalRecentItems()
            .slice(0, RAIL_ITEM_LIMIT)
            .map((item) => this.toRecentCard(item))
    );

    readonly favoriteCards = computed<DashboardRailCard[]>(() =>
        this.data
            .globalFavoriteItems()
